import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Blankslate} from '@primer/react/experimental'
import {usePropertySource} from '../hooks/use-property-source'
import {DefinitionsTable} from '@github-ui/stafftools-custom-properties-core/definitions/table'
import type {CustomPropertyDefinitionSummaryPayload} from '@github-ui/stafftools-custom-properties-core/types'
import {businessCustomPropertyDefinitionStafftoolsListPath} from '../paths'

export function DefinitionsIndexPage() {
  const {definitions} = useRoutePayload<CustomPropertyDefinitionSummaryPayload>()
  const {sourceType, source, getDefinitionDetailsPath} = usePropertySource()

  const tableData = definitions.map(definition => ({
    ...definition,
    id: definition.name,
  }))

  if (tableData.length === 0) {
    return (
      <Blankslate border>
        <Blankslate.Heading>No definitions set in this {sourceType}</Blankslate.Heading>
      </Blankslate>
    )
  }

  return (
    <DefinitionsTable
      data={tableData}
      source={source}
      getDefinitionDetailsPath={getDefinitionDetailsPath}
      getDefinitionListPath={businessCustomPropertyDefinitionStafftoolsListPath}
    />
  )
}
